from enum import Enum


class BootstrapPhase(Enum):
    """
    An enum defining the valid phases of bootstrapping. A BootstrapPhase is used to define when a BootstrapHookHandler
    is executed during cluster creation.
    """
    POST_INSTALL = 10

    @classmethod
    def valid(cls, name):
        for n in BootstrapPhase.names():
            if n == name:
                return True
        return False

    @classmethod
    def names(cls):
        return [p.name for p in list(BootstrapPhase)]

from unittest import TestCase, mock
from unittest.mock import Mock

from osbenchmark.builder.downloaders.opensearch_source_downloader import OpenSearchSourceDownloader
from osbenchmark.builder.cluster_config import ClusterConfigInstance
from osbenchmark.builder.utils.binary_keys import BinaryKeys


class OpenSearchSourceDownloaderTest(TestCase):
    def setUp(self):
        self.host = None

        self.executor = Mock()
        self.source_repository_provider = Mock()
        self.binary_builder = Mock()
        self.template_renderer = Mock()
        self.artifact_variables_provider = Mock()

        self.cluster_config = ClusterConfigInstance(names="fake", root_path="also fake", config_paths="fake2", variables={
            "source": {
                "root": {
                    "dir": "/fake/dir/for/source"
                },
                "opensearch": {
                    "subdir": "opensearch_sub-dir"
                },
                "remote": {
                    "repo": {
                        "url": "https://git.remote.fake"
                    }
                },
                "revision": "current",
                "artifact_path_pattern": "{{OSNAME}}.tar.gz",
                "build": {
                    "command": "gradle build"
                },
                "clean": {
                    "command": "gradle clean"
                }
            }
        })

        self.opensearch_source_downloader = OpenSearchSourceDownloader(self.cluster_config, self.executor,
                                                                       self.source_repository_provider, self.binary_builder,
                                                                       self.template_renderer, self.artifact_variables_provider)

    def test_download(self):
        self.artifact_variables_provider.get_artifact_variables.return_value = {"OSNAME": "fake_OS"}
        self.template_renderer.render_template_string.side_effect = ["fake clean", "fake build", "fake artifact path"]

        opensearch_binary = self.opensearch_source_downloader.download(self.host)
        self.assertEqual(opensearch_binary, {BinaryKeys.OPENSEARCH: "/fake/dir/for/source/opensearch_sub-dir/fake artifact path"})
        self.source_repository_provider.fetch_repository.assert_has_calls([
            mock.call(self.host, "https://git.remote.fake", "current", "/fake/dir/for/source/opensearch_sub-dir")
        ])
        self.binary_builder.build.assert_has_calls([
            mock.call(self.host, ["fake clean", "fake build"])
        ])
        self.artifact_variables_provider.get_artifact_variables.assert_has_calls([
            mock.call(self.host)
        ])
        self.template_renderer.render_template_string.assert_has_calls([
            mock.call("gradle clean", {"OSNAME": "fake_OS"}),
            mock.call("gradle build", {"OSNAME": "fake_OS"}),
            mock.call("{{OSNAME}}.tar.gz", {"OSNAME": "fake_OS"})
        ])

from unittest import TestCase, mock
from unittest.mock import Mock

from osbenchmark.builder.downloaders.opensearch_distribution_downloader import OpenSearchDistributionDownloader
from osbenchmark.builder.cluster_config import ClusterConfigInstance
from osbenchmark.exceptions import ExecutorError


class OpenSearchDistributionDownloaderTest(TestCase):
    def setUp(self):
        self.host = None

        self.executor = Mock()
        self.cluster_config = ClusterConfigInstance(names="fake", root_path="also fake", config_paths="fake2", variables={
            "node": {
                "root": {
                    "dir": "/fake/dir/for/download"
                }
            },
            "distribution": {
                "version": "1.2.3"
            }
        })

        self.path_manager = Mock()
        self.distribution_repository_provider = Mock()
        self.os_distro_downloader = OpenSearchDistributionDownloader(self.cluster_config, self.executor, self.path_manager,
                                                                     self.distribution_repository_provider)


        self.os_distro_downloader.distribution_repository_provider.get_download_url.return_value = "https://fake/download.tar.gz"
        self.os_distro_downloader.distribution_repository_provider.get_file_name_from_download_url.return_value = "my-distro"
        self.os_distro_downloader.distribution_repository_provider.is_cache_enabled.return_value = True

    def test_download_distro(self):
        # Check if file exists, download via curl
        self.executor.execute.side_effect = [ExecutorError("file doesn't exist"), None]

        binary_map = self.os_distro_downloader.download(self.host)
        self.assertEqual(binary_map, {"opensearch": "/fake/dir/for/download/distributions/my-distro"})

        self.executor.execute.assert_has_calls([
            mock.call(self.host, "test -f /fake/dir/for/download/distributions/my-distro"),
            mock.call(self.host, "curl -o /fake/dir/for/download/distributions/my-distro https://fake/download.tar.gz")
        ])

    def test_download_distro_exists_and_cache_enabled(self):
        # Check if file exists, download via curl
        self.executor.execute.side_effect = [None]

        binary_map = self.os_distro_downloader.download(self.host)
        self.assertEqual(binary_map, {"opensearch": "/fake/dir/for/download/distributions/my-distro"})

        self.executor.execute.assert_has_calls([
            mock.call(self.host, "test -f /fake/dir/for/download/distributions/my-distro")
        ])

    def test_download_distro_exists_and_cache_disabled(self):
        self.os_distro_downloader.distribution_repository_provider.is_cache_enabled.return_value = False
        # Check if file exists, download via curl
        self.executor.execute.side_effect = [None, None]

        binary_map = self.os_distro_downloader.download(self.host)
        self.assertEqual(binary_map, {"opensearch": "/fake/dir/for/download/distributions/my-distro"})

        self.executor.execute.assert_has_calls([
            mock.call(self.host, "test -f /fake/dir/for/download/distributions/my-distro"),
            mock.call(self.host, "curl -o /fake/dir/for/download/distributions/my-distro https://fake/download.tar.gz")
        ])

from unittest import TestCase, mock
from unittest.mock import Mock

from osbenchmark.builder.downloaders.repositories.opensearch_distribution_repository_provider import \
    OpenSearchDistributionRepositoryProvider
from osbenchmark.builder.cluster_config import ClusterConfigInstance


class OpenSearchDistributionRepositoryProviderTest(TestCase):
    def setUp(self):
        self.host = None
        self.cluster_config = ClusterConfigInstance(names=None, config_paths=None, root_path=None, variables={
            "system": {
                "runtime": {
                    "jdk": {
                        "bundled": True
                    }
                }
            },
            "distribution": {
                "repository": "release",
                "release": {
                    "cache": True
                }
            }
        })
        self.repository_url_provider = Mock()
        self.os_distro_repo_provider = OpenSearchDistributionRepositoryProvider(self.cluster_config,
                                                                                self.repository_url_provider)


    def test_get_url_bundled_jdk(self):
        self.os_distro_repo_provider.get_download_url(self.host)
        self.os_distro_repo_provider.repository_url_provider.render_url_for_key.assert_has_calls([
            mock.call(None, self.cluster_config.variables, "distribution.jdk.bundled.release_url")
        ])

    def test_get_url_unbundled_jdk(self):
        self.cluster_config.variables["system"]["runtime"]["jdk"]["bundled"] = False

        self.os_distro_repo_provider.get_download_url(self.host)
        self.os_distro_repo_provider.repository_url_provider.render_url_for_key.assert_has_calls([
            mock.call(None, self.cluster_config.variables, "distribution.jdk.unbundled.release_url")
        ])

    def test_get_file_name(self):
        file_name = self.os_distro_repo_provider.get_file_name_from_download_url(
            "https://artifacts.opensearch.org/releases/bundle/opensearch/1.2.3/opensearch-1.2.3-linux-arm64.tar.gz")

        self.assertEqual(file_name, "opensearch-1.2.3-linux-arm64.tar.gz")

    def test_is_cache_enabled_true(self):
        is_cache_enabled = self.os_distro_repo_provider.is_cache_enabled()
        self.assertEqual(is_cache_enabled, True)

    def test_is_cache_enabled_false(self):
        self.cluster_config.variables["distribution"]["release"]["cache"] = False
        is_cache_enabled = self.os_distro_repo_provider.is_cache_enabled()
        self.assertEqual(is_cache_enabled, False)
